/**
 * La marca de Orch, dibujada en línea en vez de como `<img>`.
 *
 * Los trazos son los de `assets/marca/orch-logo.svg` (el logotipo, el
 * isotipo y el icono de la aplicación comparten la misma geometría). Se
 * copian aquí en lugar de importar el fichero por dos motivos:
 *
 * - Las partes oscuras van en `currentColor` y el nodo en `--marca`, así que
 *   el logo sigue al modo claro/oscuro con una sola definición. La versión
 *   `orch-logo-dark.svg` trae su propio fondo negro: sobre el lateral oscuro
 *   se vería como una caja.
 * - El `viewBox` se recorta al contenido. Los ficheros de marca llevan el
 *   margen de una pieza suelta, que aquí descuadraría la cabecera.
 *
 * Si la marca cambia, hay que volver a copiar los trazos.
 */

interface Props {
  className?: string;
}

