// En `style` y no como atributo: `var()` en un atributo de presentación SVG
// no es fiable en todos los motores, y la ventana puede ser WebKitGTK.
const LINEA_MARCA = { stroke: "var(--marca)" } as const;
const RELLENO_MARCA = { fill: "var(--marca)" } as const;

/** La «C» con el grafo que converge en un nodo y sale por la derecha. */
function Simbolo() {
  return (
    <>
      <path
        d="M99.01 35.62 A46 46 0 1 0 99.01 84.38"
        fill="none"
        stroke="currentColor"
        strokeWidth={11}
        strokeLinecap="round"
      />
      <path
        d="M41 42 L66 60 M41 78 L66 60"
        stroke="currentColor"
        strokeWidth={6}
        strokeLinecap="round"
      />
      <path d="M66 60 L116 60" style={LINEA_MARCA} strokeWidth={6} strokeLinecap="round" />
      <circle cx={41} cy={42} r={8} fill="currentColor" />
      <circle cx={41} cy={78} r={8} fill="currentColor" />
      <circle cx={66} cy={60} r={10} style={RELLENO_MARCA} />
    </>
  );
}

/** Símbolo y nombre: la cabecera de la aplicación. */
export function Logo({ className }: Props) {
  return (
    <svg className={className} viewBox="44 44 382 112" role="img" aria-label="Orch">
      <g transform="translate(40 40)">
        <Simbolo />
      </g>
      <path transform="translate(190 130)" d={TRAZO_ORCH} fill="currentColor" />
    </svg>
  );
}

/** Sólo el símbolo, para donde el nombre ya se sobreentiende. Es decorativo. */
export function Isotipo({ className }: Props) {
  return (
    <svg className={className} viewBox="4 0 120 120" aria-hidden="true">
      <Simbolo />
    </svg>
  );
}
